use "./sim.ts" { createBalls, step, draw }

page Balls "/" {
  state paused = false
  state count = 5
  state frames = 0
  ref box
  ref balls
  ref raf

  fn add() {
    balls.push(...createBalls(1))
    count = balls.length
  }

  fn reset() {
    balls = createBalls(5)
    count = 5
    frames = 0
  }

  fn toggle() {
    paused = !paused
  }

  mount {
    balls = createBalls(5)
    let ctx = box.getContext("2d")
    let loop = () => {
      if (!paused) {
        step(balls, 400, 300)
        frames++
      }
      draw(ctx, balls, 400, 300)
      raf = requestAnimationFrame(loop)
    }
    raf = requestAnimationFrame(loop)
    cleanup { cancelAnimationFrame(raf) }
  }

  column gap=3 pad=4 {
    title "Simulación de pelotas"
    canvas ref=box id="sim" width=400 height=300
    row gap=2 {
      button "Agregar" primary -> add()
      button (paused ? "Reanudar" : "Pausar") -> toggle()
      button "Reiniciar" -> reset()
    }
    text `Pelotas: ${count}`
    text `Cuadros: ${frames}`
  }
}

