    balls = makeBalls(5)
    count = 5
    frames = 0
    if paused {
      draw(box.getContext("2d"), balls, 400, 300)
    }
  }

  mount {
    balls = makeBalls(5)
    loop()
    cleanup { cancelAnimationFrame(raf) }
  }

  column gap=3 pad=4 {
    canvas ref=box id="sim" width=400 height=300
    row gap=2 {
      button "Agregar" primary -> add()
      button `${paused ? "Reanudar" : "Pausar"}` -> toggle()
