export type Ball = { x: number; y: number; vx: number; vy: number; r: number }

export function makeBalls(n: number, w = 400, h = 300): Ball[] {
  const out: Ball[] = []
  for (let i = 0; i < n; i++) {
    const r = 10
    out.push({
      x: r + Math.random() * (w - 2 * r),
      y: r + Math.random() * (h - 2 * r),
      vx: (Math.random() - 0.5) * 6,
      vy: (Math.random() - 0.5) * 6,
      r,
    })
  }
  return out
}

export function step(balls: Ball[], w: number, h: number) {
  for (const b of balls) {
    b.vy += 0.2
    b.x += b.vx
    b.y += b.vy
    if (b.x < b.r) { b.x = b.r; b.vx = Math.abs(b.vx) }
    if (b.x > w - b.r) { b.x = w - b.r; b.vx = -Math.abs(b.vx) }
    if (b.y < b.r) { b.y = b.r; b.vy = Math.abs(b.vy) }
    if (b.y > h - b.r) { b.y = h - b.r; b.vy = -Math.abs(b.vy) }
  }
  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const a = balls[i]
      const b = balls[j]
      const dx = b.x - a.x
      const dy = b.y - a.y
      const min = a.r + b.r
      const d2 = dx * dx + dy * dy
      if (d2 < min * min) {
        const d = Math.sqrt(d2) || 0.0001
        const nx = dx / d
        const ny = dy / d
        const push = (min - d) / 2
        a.x -= nx * push
        a.y -= ny * push
        b.x += nx * push
        b.y += ny * push
        for (const p of [a, b]) {
          p.x = Math.min(Math.max(p.x, p.r), w - p.r)
          p.y = Math.min(Math.max(p.y, p.r), h - p.r)
        }
        const tvx = a.vx
        const tvy = a.vy
        a.vx = b.vx
        a.vy = b.vy
        b.vx = tvx
        b.vy = tvy
      }
    }
  }
}

export function draw(ctx: CanvasRenderingContext2D, balls: Ball[], w: number, h: number) {
  ctx.clearRect(0, 0, w, h)
  ctx.fillStyle = "#3b82f6"
  for (const b of balls) {
    ctx.beginPath()
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2)
    ctx.fill()
  }
}

